const $=s=>document.querySelector(s);const content=$('#content');let term=1,view='home',current=20,level=0,word=0,show=true;let saved={};try{saved=JSON.parse(localStorage.getItem('chn6')||'{}')}catch{};let done=saved.done||[],schedule=saved.schedule||{};const persist=()=>{try{localStorage.setItem('chn6',JSON.stringify({done,schedule}))}catch{}};
